<script>
document.querySelector('input[name="bidang_usaha"]')?.setAttribute('list','businessTypeSuggestions');
const marketEditGroups=[
    {anchor:'pengelola',param:'edit_manager',rows:@json($managerEditRows)},
    {anchor:'pedagang',param:'edit_merchant',rows:@json($merchantEditRows)}
];
marketEditGroups.forEach(group=>{const table=document.querySelector(`#${group.anchor} + .card table`);if(!table)return;[...table.querySelectorAll('tbody tr')].forEach((row,index)=>{const item=group.rows[index],actions=row.querySelector('td:last-child .d-flex');if(!item?.allowed||!actions)return;const link=document.createElement('a');const url=new URL(@json($section === 'manager' ? route('market-data.managers.index') : ($section === 'merchant' ? route('market-data.merchants.index') : route('market-data.index'))),window.location.origin);url.searchParams.set(group.param,item.id);url.hash=group.anchor;link.href=url;link.className='btn btn-sm btn-outline-primary';link.innerHTML='<i class="bi bi-pencil"></i> Edit';actions.prepend(link)})});
const managerMarkets=@json($pengelola->getCollection()->pluck('nama_pasar')->values());
const merchantMarkets=@json($pedagang->getCollection()->map(fn ($merchant) => $merchant->pengelola?->nama_pasar ?: $merchant->pengelola?->nama_perusahaan)->values());
const managerTable=document.querySelector('#pengelola + .card table');
if(managerTable){const header=managerTable.querySelector('thead tr');header.children[0]?.insertAdjacentHTML('afterend','<th>Nama Pasar</th>');[...managerTable.querySelectorAll('tbody tr')].forEach((row,index)=>{if(row.cells.length<2)return;const cell=document.createElement('td');cell.textContent=managerMarkets[index]||'—';row.cells[0].insertAdjacentElement('afterend',cell)});}
const merchantTable=document.querySelector('#pedagang + .card table');
if(merchantTable){merchantTable.querySelector('thead tr').children[1].textContent='Nama Pasar';[...merchantTable.querySelectorAll('tbody tr')].forEach((row,index)=>{if(row.cells.length<2)return;row.cells[1].textContent=merchantMarkets[index]||'—';});}
const pageSection=@json($section);
if(pageSection!=='all'){const isManager=pageSection==='manager';const managerForm=document.querySelector('input[name="nama_perusahaan"]')?.closest('.col-xl-6');const merchantForm=document.querySelector('select[name="pengelola_pasar_id"]')?.closest('.col-xl-6');const hideTable=anchor=>{const card=document.querySelector(`#${anchor} + .card`);if(card){card.style.display='none';card.nextElementSibling?.style.setProperty('display','none');}};if(isManager){merchantForm?.style.setProperty('display','none');managerForm?.classList.replace('col-xl-6','col-xl-12');hideTable('pedagang');}else{managerForm?.style.setProperty('display','none');merchantForm?.classList.replace('col-xl-6','col-xl-12');hideTable('pengelola');}const title=document.querySelector('.section-title');if(title)title.textContent=isManager?'Data Pengelola Pasar':'Data Pedagang Pasar';const subtitle=document.querySelector('.section-subtitle');if(subtitle)subtitle.textContent=isManager?'Pendataan dan rekap pengelola pasar.':'Pendataan dan rekap pedagang pasar.';}
</script>
